def normalize_amount(records):
    normalized = []
    for record in records:
        amount = record.get('amount', 0)
        if isinstance(amount, (int, float)):
            normalized.append({'id': record.get('id'), 'amount': max(0, min(1000000, amount))})
        else:
            normalized.append({'id': record.get('id'), 'amount': 0})
    return normalized

def dedupe_records(records):
    seen = set()
    unique_records = []
    for record in records:
        record_id = record.get('id')
        if record_id not in seen:
            seen.add(record_id)
            unique_records.append(record)
    return unique_records

def retry_failed(fn, attempts):
    for attempt in range(attempts):
        try:
            return fn()
        except Exception:
            if attempt == attempts - 1:
                raise
    return None

def process_with_retry(records, fn, attempts):
    for attempt in range(attempts):
        try:
            return fn(records)
        except Exception:
            if attempt == attempts - 1:
                raise
    return None

def summarize_results(results):
    total_records = 0
    successful_records = 0
    failed_records = 0
    total_amount = 0.0

    for result in results:
        total_records += 1
        if result.get('status') == 'success':
            successful_records += 1
            total_amount += result.get('amount', 0)
        else:
            failed_records += 1

    return {
        'total_records': total_records,
        'successful_records': successful_records,
        'failed_records': failed_records,
        'total_amount': total_amount
    }

def run_pipeline(records, fn, attempts):
    results = []
    for record in records:
        result = process_with_retry([record], fn, attempts)
        if result:
            results.append(result)

    return summarize_results(results)

